import { Avatar, type AvatarProps } from '../atoms/Avatar';

export type UserProfileProps = {
  name: string;
  org?: string;
  avatar?: Omit<AvatarProps, 'className'>;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function UserProfile({
  name,
  org,
  avatar,
  className,
}: UserProfileProps) {
  return (
    <div className={cn('user-profile', className)}>
      <Avatar
        type="initials"
        shape="square"
        size="s"
        status
        {...avatar}
        initials={avatar?.initials || name.split(' ').map((w) => w[0]).join('').slice(0, 2).toUpperCase()}
      />
      <div className="user-profile__info" data-sidebar-user-info="">
        <span className="user-profile__name">{name}</span>
        {org && <span className="user-profile__org">{org}</span>}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------
   User Profile (Molecule)

   Avatar + name + org/role in a row. Collapses to avatar-only
   when parent constrains width (e.g., sidebar collapsed).

   Composes: Avatar atom.
   Used in: sidebar footer, dropdowns, settings pages.
   ------------------------------------------------------------------------- */

.user-profile {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  cursor: pointer;
  padding: 4px;
  border-radius: 8px;
  text-decoration: none;
  transition: background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1);
}

.user-profile:hover {
  background-color: var(--muted);
}

.user-profile__info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: hidden;
  min-width: 0;
  transition: opacity 0.2s ease, width 0.2s ease;
}

.user-profile__name {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-profile__org {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-regular);
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Collapses in sidebar collapsed state */
.sidebar--collapsed .user-profile__info {
  opacity: 0;
  width: 0;
  overflow: hidden;
}

.sidebar--collapsed .user-profile {
  padding: 4px;
  justify-content: center;
  overflow: visible;
}

